/* =====================================================================
 * Widget Customer Service UI — Design tokens only; no hardcoded hex/px (except 0, 1px strokes)
 * Entry: scenarios/customer-service/ui/widget-floating/index.html
 * Source: DESIGN_GUIDELINES.md (dark glassmorphism + mint green)
 * ===================================================================== */

/* ---------- Reset / Global ---------- */
*, *::before, *::after { box-sizing: border-box; }

/* HTML hidden attribute must truly hide elements:
   Otherwise .handoff-banner{display:flex} / .icon-btn{display:inline-flex}
   and similar author styles, having higher specificity, will override
   [hidden]'s display:none, causing elements to be wrongly shown. */
[hidden] { display: none !important; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  font-family: var(--font-family-base);
  font-size: var(--font-size-placeholder);
  color: var(--color-text-primary);
  background: var(--color-bg-gradient);
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button { font-family: inherit; font-size: inherit; }

a { color: var(--color-brand-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ---------- 通用 icon ---------- */
.icon { display: inline-block; vertical-align: middle; flex-shrink: 0; }
.icon-text {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  line-height: 1;
}

/* ---------- 通用按钮 ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border: 1px solid var(--color-bg-border);
  border-radius: var(--radius-input);
  background: var(--color-bg-surface);
  color: var(--color-text-primary);
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.btn:hover { background: var(--color-bg-surface-strong); border-color: var(--color-text-tertiary); }
.btn:focus-visible { outline: 2px solid var(--color-brand-accent); outline-offset: 2px; }
.btn[disabled] { color: var(--color-text-disabled); cursor: not-allowed; opacity: 0.6; }

.btn--ghost { background: transparent; }
.btn--small { padding: 6px 10px; font-size: 13px; }
.btn--accent { background: var(--color-brand-accent); color: var(--color-bg-gradient-end); border-color: transparent; }
.btn--accent:hover { filter: brightness(1.05); background: var(--color-brand-accent); }

.icon-btn {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border-radius: 999px;
  border: 1px solid transparent;
  background: var(--color-bg-surface);
  color: var(--color-text-primary);
  cursor: pointer;
  transition: background 0.18s ease;
}
.icon-btn:hover { background: var(--color-bg-surface-strong); }
.icon-btn:focus-visible { outline: 2px solid var(--color-brand-accent); outline-offset: 2px; }
.icon-btn[disabled] { color: var(--color-text-disabled); cursor: not-allowed; opacity: 0.6; }

.icon-btn--primary {
  background: var(--color-brand-accent);
  color: var(--color-bg-gradient-end);
}
.icon-btn--primary:hover { filter: brightness(1.05); }

/* ---------- 状态灯（圆点） ---------- */
.led {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--color-text-disabled);
  vertical-align: middle;
  flex-shrink: 0;
}
.led[data-status="ok"] { background: var(--color-status-success); box-shadow: 0 0 0 2px rgba(143, 217, 168, 0.18); }
.led[data-status="error"] { background: var(--color-status-error); box-shadow: 0 0 0 2px rgba(224, 137, 135, 0.18); }
.led[data-status="warning"] { background: var(--color-status-warning); }
.led[data-status="info"] { background: var(--color-status-info); }
.led[data-status="unknown"] { background: var(--color-text-disabled); }
.led-label {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-right: 8px;
}

/* ---------- 页面头部 ---------- */
.page-header {
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--color-bg-surface);
  border-bottom: 1px solid var(--color-bg-border);
}
@supports (backdrop-filter: blur(20px)) {
  .page-header { backdrop-filter: var(--effect-input-blur); }
}
@supports not (backdrop-filter: blur(20px)) {
  .page-header { background: var(--color-bg-surface-strong); }
}
.page-header__inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.brand-mark {
  display: inline-flex;
  align-items: center;
  gap: var(--space-gap-brand-title);
  color: var(--color-text-secondary);
  font-size: var(--font-size-brand);
  font-weight: var(--font-weight-brand);
}
.brand-mark__logo {
  width: 20px;
  height: 20px;
  border-radius: var(--radius-logo);
  background: var(--color-brand-accent);
  display: inline-block;
}
.page-nav { display: inline-flex; gap: 16px; }
.page-nav__link {
  font-size: 13px;
  color: var(--color-text-secondary);
}
.page-nav__link:hover { color: var(--color-text-primary); }

/* ---------- 主体 ---------- */
.page-main {
  max-width: 960px;
  margin: 0 auto;
  padding: 64px 24px 160px;
}
.page-hero__title {
  margin: 0 0 12px;
  font-size: var(--font-size-title);
  font-weight: var(--font-weight-title);
  line-height: var(--line-height-title);
  color: var(--color-text-primary);
}
.page-hero__lead {
  margin: 0 0 24px;
  font-size: var(--font-size-placeholder);
  line-height: 1.6;
  color: var(--color-text-secondary);
  max-width: 60ch;
}
.page-hero__hint {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  border: 1px solid var(--color-bg-border);
  border-radius: var(--radius-input);
  background: var(--color-bg-surface);
  flex-wrap: wrap;
}

/* ---------- 浮窗容器 ---------- */
.widget {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 50;
}

/* 折叠态：仅 launcher 可见 */
.widget--collapsed .widget-panel { display: none; }
.widget--expanded .widget-launcher { display: none; }

.widget-launcher {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  border: none;
  border-radius: 999px;
  background: var(--color-brand-accent);
  color: var(--color-bg-gradient-end);
  cursor: pointer;
  font-weight: 600;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);
  transition: filter 0.18s ease, transform 0.18s ease;
}
.widget-launcher:hover { filter: brightness(1.05); transform: translateY(-1px); }
.widget-launcher:focus-visible { outline: 2px solid var(--color-text-primary); outline-offset: 2px; }
.widget-launcher__label { font-size: 14px; }

/* ---------- 浮窗面板 ---------- */
.widget-panel {
  width: 360px;
  max-width: calc(100vw - 32px);
  height: 520px;
  max-height: calc(100vh - 48px);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--color-bg-border);
  border-radius: var(--radius-card);
  background: var(--color-bg-surface);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.32);
  overflow: hidden;
}
@supports (backdrop-filter: blur(20px)) {
  .widget-panel { backdrop-filter: var(--effect-input-blur); }
}
@supports not (backdrop-filter: blur(20px)) {
  .widget-panel { background: var(--color-bg-surface-strong); }
}

.widget-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--color-bg-border);
}
.widget-panel__brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.widget-panel__logo {
  width: 24px;
  height: 24px;
  border-radius: var(--radius-logo);
  background: var(--color-brand-accent);
}
.widget-panel__title {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}
.widget-panel__title strong {
  color: var(--color-text-primary);
  font-size: 15px;
  font-weight: 600;
}
.widget-panel__sub {
  color: var(--color-text-secondary);
  font-size: 12px;
}
.widget-panel__actions { display: inline-flex; gap: 6px; }

/* ---------- 消息列表 ---------- */
.widget-panel__messages {
  flex: 1 1 auto;
  overflow-y: auto;
  margin: 0;
  padding: 16px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  scrollbar-width: thin;
  scrollbar-color: var(--color-bg-border) transparent;
}
.widget-panel__messages::-webkit-scrollbar { width: 6px; }
.widget-panel__messages::-webkit-scrollbar-thumb {
  background: var(--color-bg-border);
  border-radius: 999px;
}

.msg {
  max-width: 86%;
  padding: 10px 12px;
  border-radius: var(--radius-input);
  font-size: 14px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}
.msg--user {
  align-self: flex-end;
  background: var(--color-brand-accent);
  color: var(--color-bg-gradient-end);
  border-bottom-right-radius: 4px;
}
.msg--ai {
  align-self: flex-start;
  background: var(--color-bg-surface-strong);
  color: var(--color-text-primary);
  border-bottom-left-radius: 4px;
  border: 1px solid var(--color-bg-border);
}
.msg--system {
  align-self: center;
  background: transparent;
  color: var(--color-text-tertiary);
  font-size: 12px;
  padding: 4px 8px;
}

.msg__cite {
  margin-top: 6px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--color-text-secondary);
  opacity: 0.85;
}
.msg__cite::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--color-status-success);
}

/* AI 输入指示（"…"） */
.msg--typing {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 12px 14px;
  border-radius: var(--radius-input);
  background: var(--color-bg-surface-strong);
  border: 1px solid var(--color-bg-border);
}
.msg--typing span {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--color-text-secondary);
  animation: typingDot 1.2s infinite ease-in-out;
}
.msg--typing span:nth-child(2) { animation-delay: 0.18s; }
.msg--typing span:nth-child(3) { animation-delay: 0.36s; }
@keyframes typingDot {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-3px); opacity: 1; }
}

/* ---------- 转人工 banner ---------- */
.handoff-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  margin: 8px 12px 12px;
  border-radius: var(--radius-input);
  background: var(--color-bg-surface-strong);
  border: 1px solid var(--color-bg-border);
  font-size: 13px;
  color: var(--color-text-primary);
}
.handoff-banner[data-state="waiting"] .handoff-banner__dot { background: var(--color-status-warning); }
.handoff-banner[data-state="connected"] .handoff-banner__dot { background: var(--color-status-success); }
.handoff-banner[data-state="canceled"], .handoff-banner[data-state="timeout"] {
  color: var(--color-text-secondary);
}
.handoff-banner__dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--color-status-info);
  flex-shrink: 0;
}
.handoff-banner__text {
  flex: 1;
}

/* ---------- 输入区 ---------- */
.widget-panel__foot {
  border-top: 1px solid var(--color-bg-border);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.composer {
  display: flex;
  align-items: center;
  gap: 8px;
}
.composer__input {
  flex: 1;
  padding: var(--space-input-padding-y) var(--space-input-padding-x);
  border: 1px solid var(--color-bg-border);
  border-radius: var(--radius-input);
  background: var(--color-input-bg);
  color: var(--color-text-primary);
  font-size: var(--font-size-placeholder);
  outline: none;
}
.composer__input::placeholder { color: var(--color-text-placeholder); }
.composer__input:focus { border-color: var(--color-brand-accent); }
.composer__input[disabled] { color: var(--color-text-disabled); }

.composer__hint {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--color-text-tertiary);
}
.hint-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--color-status-info);
  display: inline-block;
}
.composer__hint[data-tone="kb"] .hint-dot { background: var(--color-status-success); }
.composer__hint[data-tone="handoff"] .hint-dot { background: var(--color-status-warning); }
.composer__hint[data-tone="error"] .hint-dot { background: var(--color-status-error); }

/* ---------- 工具调用卡片（tool-calling）---------- */
.tool-card {
  align-self: flex-start;
  max-width: 92%;
  border: 1px solid var(--color-bg-border);
  border-radius: var(--radius-input);
  background: var(--color-bg-surface-strong);
  overflow: hidden;
}
.tool-card__head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--color-bg-border);
  font-size: 13px;
  color: var(--color-text-secondary);
}
.tool-card__name {
  font-weight: 600;
  color: var(--color-text-primary);
  font-family: var(--font-family-base);
}
.tool-card__status {
  margin-left: auto;
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--color-bg-surface);
  color: var(--color-text-secondary);
}
.tool-card__status[data-s="running"] { color: var(--color-status-info); }
.tool-card__status[data-s="ok"] { color: var(--color-status-success); }
.tool-card__status[data-s="error"] { color: var(--color-status-error); }
.tool-card__body {
  margin: 0;
  padding: 10px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--color-text-primary);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 200px;
  overflow: auto;
}
.tool-card__body--muted { color: var(--color-text-tertiary); }
.tool-card__body--err { color: var(--color-status-error); }

/* ---------- 响应式 ---------- */
@media (max-width: 480px) {
  .widget { right: 12px; bottom: 12px; }
  .widget-panel { width: calc(100vw - 24px); height: calc(100vh - 100px); }
  .page-main { padding: 24px 16px 200px; }
}

